script:
card({ name: "Memory match", icon: 'cards', permissions: ['sound'] });
const words = {
  hint: "Turn two cards. A pair is yours.",
  moves: "{p0} moves",
  done: "All pairs found!",
  won: "{p0} found the most",
  again: "Deal again",
  open: "That card is already up",
};

const faces = ['🍎', '🍋', '🍇', '🍒', '🥝', '🍑', '🍍', '🥥'];

function init() {
  return { deck: null, open: [], found: [], score: {}, names: {}, moves: 0 };
}

// ctx.random() shuffles the same way on every phone.
function deal(s, ctx) {
  const d = faces.concat(faces);
  for (let i = d.length - 1; i > 0; i--) {
    const j = Math.floor(ctx.random() * (i + 1));
    const t = d[i];
    d[i] = d[j];
    d[j] = t;
  }
  s.deck = d;
}

on.flip = (s, args, ctx) => {
  if (!s.deck) deal(s, ctx);
  const i = args.card;
  if (s.found.includes(i) || s.open.includes(i)) throw words.open;
  // Two that didn't match turn back over first.
  if (s.open.length === 2) s.open = [];
  s.names[ctx.author] = ctx.authorName;
  s.score[ctx.author] = s.score[ctx.author] || 0;
  s.open.push(i);
  if (s.open.length < 2) {
    ctx.sound('tap');
    return;
  }
  s.moves++;
  const [a, b] = s.open;
  if (s.deck[a] !== s.deck[b]) {
    ctx.sound('buzz');
    return;
  }
  s.found.push(a, b);
  s.open = [];
  s.score[ctx.author]++;
  ctx.sound(s.found.length === s.deck.length ? 'win' : 'coin');
};

on.again = (s, args, ctx) => {
  const fresh = init();
  deal(fresh, ctx);
  return fresh;
};

function view(s) {
  const cards = [];
  for (let i = 0; i < faces.length * 2; i++) {
    const up = s.deck && (s.open.includes(i) || s.found.includes(i));
    cards.push(button(up ? s.deck[i] : '', 'flip', { card: i }, {
      size: 'large',
      tone: s.found.includes(i) ? 'success' : up ? 'accent' : undefined,
    }));
  }
  const done = s.deck && s.found.length === s.deck.length;
  const ids = Object.keys(s.score).sort((a, b) => s.score[b] - s.score[a]);
  return column([
    text(done ? words.done : words.hint, { bold: true, align: 'center', tone: done ? 'success' : undefined }),
    grid(4, cards),
    row([
      badge(words.moves.replace('{p0}', s.moves)),
      ...ids.map((id, i) => badge(s.names[id] + ' ' + s.score[id], { tone: i === 0 && s.score[id] > 0 ? 'accent' : undefined })),
    ], { align: 'center' }),
    done && ids.length > 1 && text(words.won.replace('{p0}', s.names[ids[0]]), { align: 'center' }),
    done && button(words.again, 'again', null, { tone: 'accent', align: 'center' }),
  ]);
}
